ssize_t WritePSDChannels(const PSDInfo *psd_info, const ImageInfo *image_info,
                         Image *image, Image *next_image,
                         MagickOffsetType size_offset, MagickBooleanType separate)
{
  size_t number_pixels;
  register ssize_t x;
  ssize_t count;
  ssize_t bytes_written;
  MagickBooleanType proceed = MagickTrue;
  void *compact_pixels = NULL;
  register Quantum *p = (Quantum *) NULL;
  Quantum *cmyk_pixels = (Quantum *) NULL;
  size_t cmyk_length = 0;

  (void) psd_info;  /* Currently unused but passed for context */
  (void) image_info;
  (void) next_image;
  (void) size_offset;
  (void) separate;

  number_pixels = image->columns * image->rows;

  if (image->storage_class == PseudoClass)
  {
    compact_pixels = (void *) AcquireQuantumMemory(number_pixels, sizeof(PixelPacket));
    if (compact_pixels == (void *) NULL)
      return (0);
    p = (Quantum *) compact_pixels;
    for (x = 0; x < (ssize_t) number_pixels; x++)
    {
      register PixelPacket *q = (PixelPacket *) compact_pixels + x;

      *p++ = q->red;
      *p++ = q->green;
      *p++ = q->blue;
    }
  }

  /* Write channels for RGB, CMYK, etc. as needed */
  if (image->colorspace == CMYKColorspace)
  {
    cmyk_length = number_pixels * 4;
    cmyk_pixels = (Quantum *) AcquireQuantumMemory(number_pixels, 4 * sizeof(Quantum));
    if (cmyk_pixels == (Quantum *) NULL)
      return (0);
    p = cmyk_pixels;
    for (x = 0; x < (ssize_t) number_pixels; x++)
    {
      register PixelPacket *q = GetPixelInfoPixel(image, x);

      *p++ = q->red;
      *p++ = q->green;
      *p++ = q->blue;
      *p++ = q->opacity;
    }

    count = (ssize_t) cmyk_length;
    bytes_written = count;
  }
  else
  {
    bytes_written = (ssize_t) (image->columns * image->rows * 3);
  }

  if (compact_pixels != (void *) NULL)
    compact_pixels = RelinquishMagickMemory(compact_pixels);

  if (cmyk_pixels != (Quantum *) NULL)
    cmyk_pixels = (Quantum *) RelinquishMagickMemory(cmyk_pixels);

  if (proceed == MagickFalse)
    return (0);

  return bytes_written;
}

ssize_t WritePSDChannels(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, MagickOffsetType size_offset, MagickBooleanType separate)
{
  ssize_t total_bytes = 0;
  MagickBooleanType is_compressed = MagickFalse;
  MagickPixelPacket *compact_pixels = NULL;
  size_t width = image->columns;
  size_t height = image->rows;
  size_t channels = 0;

  if (!image || !psd_info)
    return 0;

  if (next_image && (next_image->compression != NoCompression))
    is_compressed = MagickTrue;

  if (is_compressed)
    compact_pixels = (MagickPixelPacket *) AcquireCriticalMemory(width * height * sizeof(*compact_pixels));
  else
    compact_pixels = GetVirtualPixels(image, 0, 0, width, height, NULL);

  if (!compact_pixels)
    return 0;

  switch (image->colorspace) {
    case RGBColorspace:
      channels = 3;
      break;
    case CMYKColorspace:
      channels = 4;
      break;
    default:
      channels = 3;
      break;
  }

  for (size_t ch = 0; ch < channels; ch++) {
    // Write each channel based on compression type and storage class
    if (image->storage_class == PseudoClass)
      total_bytes += WritePSDChannel(psd_info, image_info, image, compact_pixels, ch, size_offset);
    else
      total_bytes += WritePSDChannel(psd_info, image_info, image, compact_pixels, ch, size_offset);
  }

  // Handle masks or additional channels if present
  if (image->mask != (PixelIterator *) NULL) {
    // Write mask channel
    total_bytes += WritePSDChannel(psd_info, image_info, image, compact_pixels, channels, size_offset);
    channels++;
  }

  if (separate)
    total_bytes += WriteSeparateChannels(psd_info, image_info, image, next_image, size_offset);

  if (is_compressed)
    compact_pixels = (MagickPixelPacket *) RelinquishMagickMemory(compact_pixels);

  return (total_bytes > 0) ? total_bytes : 0;
}

ssize_t WritePSDChannels(const PSDInfo *psd_info, const ImageInfo *image_info,
                         Image *image, Image *next_image,
                         MagickOffsetType size_offset, MagickBooleanType separate)
{
    ssize_t count = 0;
    MagickOffsetType offset = 0;
    MagickPixelPacket *compact_pixels = NULL;
    size_t number_pixels = image->columns * image->rows;
    size_t length = MagickPathExtent;

    if ((next_image != (Image *) NULL) && (next_image->compression != NoCompression))
    {
        compact_pixels = AcquireCompactPixelPacket(image, compact_pixels, number_pixels);
        if (compact_pixels == (MagickPixelPacket *) NULL)
            return (0);
    }

    if (image->storage_class == PseudoClass)
    {
        if (image->colors > 0)
        {
            count = WritePSDChannel(psd_info, image_info, image, 0, 0, separate, &offset);
            if (count <= 0)
                goto cleanup;
        }
    }
    else
    {
        if ((image->colorspace == RGBColorspace) || (image->colorspace == HSLColorspace))
        {
            count = WritePSDChannel(psd_info, image_info, image, 0, 0, separate, &offset);
            if (count <= 0)
                goto cleanup;

            count = WritePSDChannel(psd_info, image_info, image, 1, 0, separate, &offset);
            if (count <= 0)
                goto cleanup;

            count = WritePSDChannel(psd_info, image_info, image, 2, 0, separate, &offset);
            if (count <= 0)
                goto cleanup;
        }

        if ((image->alpha_trait != UndefinedAlpha) && (image->alpha_trait != NoAlpha))
        {
            count = WritePSDChannel(psd_info, image_info, image, 3, 0, separate, &offset);
            if (count <= 0)
                goto cleanup;
        }
    }

    if (separate != MagickFalse)
    {
        if (image->mask != (Image *) NULL)
        {
            count = WritePSDChannel(psd_info, image_info, image, 0, 0, MagickFalse, &offset);
            if (count <= 0)
                goto cleanup;
        }
    }

    size_offset += offset;

cleanup:
    if (compact_pixels != (MagickPixelPacket *) NULL)
        compact_pixels = DestroyCompactPixelPacket(image, compact_pixels);

    return (ssize_t) offset;
}

ssize_t WritePSDChannels(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, MagickOffsetType size_offset, MagickBooleanType separate) {
    ssize_t count = 0;
    MagickBooleanType status = MagickTrue;
    size_t number_pixels;
    PixelTrait traits;
    unsigned char *compact_pixels = NULL;
    MagickOffsetType offset = 0;

    number_pixels = image->columns * image->rows;

    if (next_image != (Image *) NULL) {
        if (next_image->compression != psd_info->compression) {
            compact_pixels = (unsigned char *) AcquireMemory(number_pixels * sizeof(*compact_pixels));
            if (compact_pixels == (unsigned char *) NULL)
                return 0;

            if (next_image->storage_class == PseudoClass) {
                for (size_t i = 0; i < number_pixels; i++)
                    compact_pixels[i] = (unsigned char) GetPixelRed(next_image, i);
            }
            else {
                for (size_t i = 0; i < number_pixels; i++) {
                    compact_pixels[i] = (unsigned char) (QuantumScale * GetPixelRed(next_image, i));
                }
            }
        }
    }

    if (image->colorspace == CMYKColorspace) {
        traits = GetPixelChannelTraits(image, RedPixelChannel);
        if (traits != UndefinedPixelTrait)
            count += WritePSDChannel(psd_info, image_info, image, RedPixelChannel, compact_pixels, size_offset + offset, &offset, separate);

        traits = GetPixelChannelTraits(image, GreenPixelChannel);
        if (traits != UndefinedPixelTrait)
            count += WritePSDChannel(psd_info, image_info, image, GreenPixelChannel, compact_pixels, size_offset + offset, &offset, separate);

        traits = GetPixelChannelTraits(image, BluePixelChannel);
        if (traits != UndefinedPixelTrait)
            count += WritePSDChannel(psd_info, image_info, image, BluePixelChannel, compact_pixels, size_offset + offset, &offset, separate);

        traits = GetPixelChannelTraits(image, BlackPixelChannel);
        if (traits != UndefinedPixelTrait)
            count += WritePSDChannel(psd_info, image_info, image, BlackPixelChannel, compact_pixels, size_offset + offset, &offset, separate);
    }
    else {
        traits = GetPixelChannelTraits(image, RedPixelChannel);
        if (traits != UndefinedPixelTrait)
            count += WritePSDChannel(psd_info, image_info, image, RedPixelChannel, compact_pixels, size_offset + offset, &offset, separate);

        traits = GetPixelChannelTraits(image, GreenPixelChannel);
        if (traits != UndefinedPixelTrait)
            count += WritePSDChannel(psd_info, image_info, image, GreenPixelChannel, compact_pixels, size_offset + offset, &offset, separate);

        traits = GetPixelChannelTraits(image, BluePixelChannel);
        if (traits != UndefinedPixelTrait)
            count += WritePSDChannel(psd_info, image_info, image, BluePixelChannel, compact_pixels, size_offset + offset, &offset, separate);
    }

    if (compact_pixels != (unsigned char *) NULL)
        compact_pixels = RelinquishMemory(compact_pixels);

    if (status != MagickTrue)
        return 0;

    return count;
}

ssize_t WritePSDImageChannels(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, MagickOffsetType size_offset, MagickBooleanType separate)
{
    MagickOffsetType offset = size_offset;
    size_t length = 0;
    ssize_t count = 0;

    if (next_image != (Image *) NULL)
    {
        if (next_image->compression == ZipCompression)
        {
            if (image->storage_class == PseudoClass)
                length = image->columns * image->rows * GetPixelAlpha(image, 0, 0);
            else
                length = image->columns * image->rows * image->channels;

            if (length > 0)
            {
                unsigned char *compact_pixels = (unsigned char *) AcquireMemory(length * sizeof(unsigned char));
                if (compact_pixels == (unsigned char *) NULL)
                    return 0;

                count += WriteBlobData(image, offset, length, compact_pixels);
                compact_pixels = (unsigned char *) RelinquishMemory(compact_pixels);
            }
        }

        if (image->colorspace == RGBColorspace)
        {
            if (separate)
            {
                count += WriteBlobData(image, offset, image->columns * image->rows, image->red);
                count += WriteBlobData(image, offset, image->columns * image->rows, image->green);
                count += WriteBlobData(image, offset, image->columns * image->rows, image->blue);
            }
            else
            {
                size_t channel_bytes = image->columns * image->rows * sizeof(PixelPacket);
                count += WriteBlobData(image, offset, channel_bytes, image->pixels);
            }
        }

        else if (image->colorspace == CMYKColorspace)
        {
            if (separate)
            {
                count += WriteBlobData(image, offset, image->columns * image->rows, image->cyan);
                count += WriteBlobData(image, offset, image->columns * image->rows, image->magenta);
                count += WriteBlobData(image, offset, image->columns * image->rows, image->yellow);
                count += WriteBlobData(image, offset, image->columns * image->rows, image->black);
            }
            else
            {
                size_t channel_bytes = image->columns * image->rows * sizeof(PixelPacket);
                count += WriteBlobData(image, offset, channel_bytes, image->pixels);
            }
        }
    }

    return count;
}
